import FreeCAD
import PartDesign

# Create a new document
doc = FreeCAD.newDocument("answer")

# Create a PartDesign Body
body = doc.addObject("PartDesign::Body", "Body")

# Create a cylindrical smooth shaft
smooth_shaft = body.newObject("PartDesign::Cylinder", "SmoothShaft")
smooth_shaft.Radius = 15  # Diameter / 2
smooth_shaft.Height = 50
smooth_shaft.Placement.Base = FreeCAD.Vector(0, 0, 0)

# Create keyway parameters
keyway_width = 7
keyway_depth = 4
keyway_height = 20
num_keyway = 1

# Create keyway features
for i in range(num_keyway):
    keyway = body.newObject("PartDesign::Pocket", f"Keyway{i+1}")
    keyway.Base = smooth_shaft
    keyway.Length = keyway_height
    keyway.LengthFuzz = 0
    keyway.BaseOffset = keyway_width / 2
    keyway.BaseAngle = 0
    keyway.BaseAxis = FreeCAD.Vector(0, 0, 1)
